compact/posix/windsurf/ollama-embed/deep.copy:
# Keep generated configuration files out of version control.
echo .chunkhound.json >> .gitignore
# Configure ChunkHound with Ollama embeddings and DeepSeek for research. Embedding and LLM providers are independent — either works without the other. Field details: https://chunkhound.ai/docs/configuration/
# You'll need: DeepSeek API key
cat > .chunkhound.json <<'CHUNKHOUND_EOF'
{
  "embedding": {
    "provider": "openai",
    "model": "qwen3-embedding",
    "base_url": "http://localhost:11434/v1"
  },
  "llm": {
    "provider": "deepseek",
    "model": "deepseek-v4-flash",
    "api_key": "<YOUR_DEEPSEEK_API_KEY>"
  }
}
CHUNKHOUND_EOF
# Configure Windsurf to connect to ChunkHound via MCP.
if [ -f ~/.codeium/windsurf/mcp_config.json ]; then
cat <<'CHUNKHOUND_EOF'
~/.codeium/windsurf/mcp_config.json already exists — merge this block into it manually:
{
  "mcpServers": {
    "ChunkHound": {
      "command": "chunkhound",
      "args": [
        "mcp"
      ]
    }
  }
}
CHUNKHOUND_EOF
else
mkdir -p ~/.codeium/windsurf
cat > ~/.codeium/windsurf/mcp_config.json <<'CHUNKHOUND_EOF'
{
  "mcpServers": {
    "ChunkHound": {
      "command": "chunkhound",
      "args": [
        "mcp"
      ]
    }
  }
}
CHUNKHOUND_EOF
fi
# Build ChunkHound's search index for this project.
chunkhound index .

